  "importantPoints": [
    "Elements contain one kind of atom.",
    "Compounds are pure substances with elements chemically combined in fixed proportions.",
    "Mixtures contain two or more substances physically combined and can have variable composition.",
    "A uniform appearance does not prove that a sample is a compound.",
    "Chemical formulas communicate the identity and atom ratio of compounds.",
    "Mixtures can often be separated by physical methods.",
    "Filtration, evaporation, distillation and chromatography exploit different physical properties.",
    "Physical change does not create a new chemical substance; chemical change does.",
    "Solutions are homogeneous mixtures; suspensions are heterogeneous.",
    "The correct separation method depends on the properties of the components."
  ],
  "keyTerms": [
    {
      "term": "Matter",
      "definition": "Anything that has mass and occupies space."
    },
    {
      "term": "Element",
      "definition": "A pure substance made of one kind of atom."
    },
    {
      "term": "Atom",
      "definition": "The smallest unit retaining the chemical identity of an element."
    },
    {
      "term": "Compound",
      "definition": "A pure substance formed by chemical combination of different elements in fixed proportions."
    },
    {
      "term": "Mixture",
      "definition": "Two or more substances physically combined in variable proportions."
    },
    {
      "term": "Homogeneous mixture",
      "definition": "A mixture with uniform composition at the relevant scale."
    },
    {
      "term": "Heterogeneous mixture",
      "definition": "A mixture with non-uniform composition."
    },
    {
      "term": "Solution",
      "definition": "A homogeneous mixture of solute and solvent."
    },
    {
      "term": "Solute",
      "definition": "The substance dispersed/dissolved in a solvent."
    },
    {
      "term": "Solvent",
      "definition": "The medium that dissolves the solute in a solution."
    },
    {
      "term": "Suspension",
      "definition": "A heterogeneous mixture containing particles large enough to settle."
    },
    {
      "term": "Chromatography",
      "definition": "A separation technique based on different movement/affinity of components."
    },
    {
      "term": "Distillation",
      "definition": "A separation method using differences in boiling points."
    },
    {
      "term": "Alloy",
      "definition": "A metallic mixture made by combining elements, usually at least one metal."
    }
  ]
